    "summaryLong": "앤터러스 뉴클리어가 개발 중인 Mark-0 마이크로원자로가 임계 달성에 성공했다. 이는 미국 에너지부 지원 프로그램 참여 개발사 중 첫 번째 임계 달성 사례로 평가된다. 소형모듈원자로(SMR) 기술의 실증 단계 진입을 의미하며, 미국의 차세대 원자력 기술 개발 추진력을 보여준다. 향후 상용화 단계로의 진행 가능성을 시사한다.",
