    "title": "미국 에너지부(DOE), 소형모듈원자로 배치 가속화를 위해 8개사에 9,400만 달러 지원",
    "summary": "미국 에너지부(DOE)가 소형모듈원자로 배치 가속화를 위해 8개 기업에 총 9,400만 달러를 지원한다.",
    "summaryLong": "미국 에너지부(DOE)는 소형모듈원자로의 상용화 속도를 높이기 위해 8개 기업에 대규모 자금을 지원한다. 9,400만 달러 규모의 지원은 미국 정부의 소형모듈원자로 개발 정책의 강한 의지를 보여준다. 지원 대상 기업들은 기술 개발, 제조 인프라 구축, 인허가 취득 등 다양한 분야에서 활용할 수 있다. 이러한 정부 지원은 소형모듈원자로의 시장 진입 시간을 단축하고 산업 경쟁력 강화에 기여할 것으로 기대된다.",
