    "summary": "타임 매거진(Time Magazine)이 홀텍 인터내셔널을 미국 에너지산업 10대 영향력 기업 중 하나이자, 핵에너지 분야에선 넥스테라(NextEra) 다음으로 유일하게 선정했다.",
