    "title": "Aker Solutions, Rolls-Royce SMR과 MOU 체결",
    "summary": "Aker Solutions가 Rolls-Royce SMR과 소형모듈원자로 에너지 프로젝트 양해각서를 체결했다.",
    "summaryLong": "노르웨이 해상 에너지 기업 Aker Solutions가 영국의 Rolls-Royce SMR과 소형모듈원자로 에너지 프로젝트 협력을 위한 양해각서(MOU)를 체결했다. 이는 산업계와 에너지 공급자 간 SMR 활용을 위한 협력 확대를 보여준다. Aker Solutions의 해상 기술과 Rolls-Royce의 SMR 기술 결합은 해상·육상 에너지 공급 다양화에 기여할 것으로 예상된다. 양사는 향후 구체적인 프로젝트 개발을 진행할 예정이다.",
