    "summaryLong": "ORF 미들이스트(ORF Middle East)는 인도의 소형모듈원자로(SMR) 전략을 보도했다. 인도는 에너지 자립과 탈탄소 목표 달성을 위해 SMR 개발에 대규모 투자를 추진하고 있으며, 이는 인도 정부의 국책 에너지 정책의 일환이다. SMR은 인도의 분산된 지역 전력 공급과 산업용 열 수요 충족을 위한 전략적 기술로 평가되고 있다.",
