    "summary": "영국의 Rolls-Royce가 자사 소형모듈원자로에 대한 규제 정당성(Regulatory justification)을 제시하고 있다.",
    "summaryLong": "영국의 Rolls-Royce는 자사가 개발 중인 소형모듈원자로(SMR)에 대해 규제 당국에 규제 정당성을 입증하는 과정을 진행하고 있다. 규제 정당성 검토는 원자로 도입의 사회적·경제적·환경적 편익을 증명하는 단계로, 영국의 원자력 규제 체계에서 필수 절차이다. Rolls-Royce의 SMR은 영국의 에너지 안정성과 탈탄소화 목표에 부합하는 기술로 평가되고 있다. 규제 정당성 검토의 완료는 향후 허가 및 상용화 단계로의 진행을 앞당길 것으로 예상된다.",
