    "summary": "테라파워(TerraPower)의 나트륨(Natrium) 소형모듈원자로가 미국 원자력규제위원회(NRC) 안전심사를 일정보다 앞서 완료하였으며, 2026년 3월 건설허가(CP) 발급으로 이어질 예정이다.",
