    "summaryLong": "미국-일본 합작사 지이이(GEH, GE Hitachi)가 개발한 BWRX-300 소형모듈원자로가 영국의 포괄설계평가(GDA) 2단계를 성공적으로 통과하였다. BWRX-300은 자연순환 냉각 등 혁신적 안전 기술을 적용한 경수로형 SMR로, GDA 2단계 통과는 기본 설계의 기술적 타당성이 인정되었음을 의미한다. 향후 최종단계(Step 3)를 거쳐 2027년경 설계 승인 획득이 예상되며, 이는 지이이의 영국 내 SMR 시장 진출을 가속화할 것으로 기대된다. 롤스로이스와 함께 진행 중인 경쟁적 인허가는 영국의 SMR 상용화 및 제조 산업 육성에 긍정적 영향을 미칠 것으로 전망된다.",
