    "summary": "미국 테네시밸리청(TVA)이 테네시주에서 미국 내 첫 상용 소형모듈원자로 개발을 추진 중이다.",
    "summaryLong": "테네시밸리청(TVA)은 클린치 강(Clinch River) 부지에서 미국 첫 상용 소형모듈원자로 건설 프로젝트를 진행하고 있다. 이 프로젝트는 미국 에너지부(DOE)의 지원 대상으로 선정되어 연방 정부 자금을 확보했다. 완성될 경우 미국의 분산형 저탄소 전력 공급 체계 구축에 중요한 역할을 할 것으로 기대된다. 프로젝트의 성공은 향후 미국 내 소형모듈원자로 상용화의 모델이 될 수 있다.",
