    "title": "듀크 에너지(Duke Energy), 미국 소형모듈원자로 배치 확대 지원",
    "summary": "듀크 에너지가 미국 에너지부(DOE)의 신규 핵 투자 정책을 지지하며 소형모듈원자로 배치 확대에 협력하겠다고 밝혔다.",
    "summaryLong": "주요 전력 회사인 듀크 에너지는 미국 에너지부의 신규 핵 투자 정책을 지지하며 소형모듈원자로 배치 확대에 참여할 의사를 표명했다. 이는 에너지 회사들의 탄소 중립 에너지원으로서 소형모듈원자로에 대한 관심 증가를 보여준다. 듀크 에너지의 지원은 소형모듈원자로 상용화의 시장 확대에 긍정적 신호로 작용할 것으로 예상된다. 향후 다른 에너지 기업들의 참여 확대도 기대된다.",
