    "summaryLong": "미국 원자력규제위원회(NRC)는 테네시밸리공사(TVA)가 진행하는 소형모듈원자로(SMR) 개발 프로젝트에 대해 긍정적인 심사 결과를 바탕으로 승인을 권고했다. 이는 미국 내 소형모듈원자로(SMR) 상용화 진전에 있어 중요한 이정표로, 규제 당국이 기술 안전성과 구현 가능성을 인정했음을 의미한다. 테네시밸desarley공사(TVA)는 미국 남동부 지역의 전력 공급을 담당하는 주요 공사로, 이 프로젝트의 진행은 지역 에너지 안보 강화에도 기여할 것으로 보인다. 향후 정식 승인 획득 시 소형모듈원자로(SMR)의 실증화 단계로 한 걸음 더 나아갈 수 있을 것으로 예상된다.",
