    "summaryLong": "프랑스 전력공사(EDF)는 야심찬 소형모듈원자로(SMR) 개발 목표를 수립했으며, 2026년까지 설계를 완료하고 2050년까지 총 30기를 생산할 계획이다. 이는 프랑스의 에너지 전환 정책과 탄소 중립 목표 달성을 위한 핵심 전략으로, 소형모듈원자로(SMR)를 미래 에너지 믹스의 중요 요소로 보고 있음을 보여준다. 프랑스 전력공사(EDF)는 유럽에서 가장 큰 에너지 회사 중 하나로, 이러한 투자는 유럽 전역의 소형모듈원자로(SMR) 산업 발전을 견인할 수 있다. 성공적인 추진 시 프랑스뿐 아니라 유럽 전체의 에너지 안보와 기후 목표 달성에 상당한 기여를 할 것으로 기대된다.",
