    "summary": "미국 콜로라도주 푸에블로가 소형모듈원자로 도입 가능성을 검토하고 있다.",
    "summaryLong": "미국 콜로라도주의 푸에블로시가 지역 에너지 공급 확대를 위해 소형모듈원자로 도입 타당성을 검토 중이다. 이는 미국 내 소형모듈원자로의 지역 수용성을 높이기 위한 움직임으로 해석된다. 푸에블로는 에너지 기반 경제 구조를 갖춘 지역으로, 원자력 에너지는 탄소 감축과 지역 경제 활성화를 동시에 달성할 수 있는 방안으로 주목받고 있다. 검토 결과에 따라 구체적인 사업 추진 여부가 결정될 것으로 예상된다.",
